#!/usr/bin/env python3
# pinneberg Stufe 2. Tauscht nur die Pinneberg-Stellen. DSL, Gas, USV und EG-SoH bleiben bytegleich.
from __future__ import annotations
import base64, hashlib, json, os, shutil, subprocess, sys
from datetime import datetime
from pathlib import Path

DASH = Path("/home/fmg/prepper-dashboard")
NEED = {
    "ups_manager.py": ("6658f0ef31f060f4", None),
    "lage_pages.py": ("4b2b0b63b2af80b5", 215701),
    "prepper_sdr.py": ("533b6f9db8da0bcb", None),
    "pinneberg_rolle.py": ("981cacdbf5a81348", None),
}
DASH_OK = ("6d9fe2860fc63671", "dcb452f3cefef258")

def load():
    raw = PAYLOAD if isinstance(PAYLOAD, dict) else json.loads(PAYLOAD)
    pairs = [(base64.b64decode(a).decode("utf-8"), base64.b64decode(b).decode("utf-8")) for a, b in raw["pairs"]]
    return raw, pairs

def sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

def prefix_ok(name, data: bytes) -> bool:
    if name == "dashboard.py":
        return sha(data).startswith(DASH_OK)
    head, size = NEED[name]
    if not sha(data).startswith(head):
        return False
    return size is None or len(data) == size

def syntax(data: bytes, name: str):
    try:
        compile(data, name, "exec")
    except SyntaxError as exc:
        return "Zeile %s: %s" % (exc.lineno, exc.msg)
    return None

def tausch(data: bytes, pairs, rueck=False) -> bytes:
    out = data
    seq = [(b, a) for a, b in pairs] if rueck else pairs
    for a, b in seq:
        raw_a, raw_b = a.encode(), b.encode()
        if out.count(raw_a) != 1:
            raise RuntimeError("Stelle nicht genau einmal")
        out = out.replace(raw_a, raw_b, 1)
    return out

def rest(data: bytes, pairs, neu: bool) -> bytes:
    out = data
    for a, b in pairs:
        part = (b if neu else a).encode()
        if out.count(part) != 1:
            raise RuntimeError("Restpruefung")
        out = out.replace(part, b"", 1)
    return out

def fenster(now=None):
    try:
        from zoneinfo import ZoneInfo
        jetzt = now or datetime.now(ZoneInfo("Europe/Berlin"))
    except Exception as exc:
        return False, "Zeitzone nicht verfuegbar (%s)" % exc
    m = jetzt.minute
    return (not (m >= 45 or m <= 4)), "Berlin %s Minute %02d" % (jetzt.strftime("%Y-%m-%d %H:%M"), m)

def schreiben(path: Path, data: bytes):
    mode = path.stat().st_mode & 0o777 if path.exists() else 0o644
    tmp = path.with_name("." + path.name + ".tmp-pinneberg2")
    if tmp.exists():
        raise RuntimeError("temporaere Datei existiert")
    try:
        with open(tmp, "wb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(tmp, mode)
        os.replace(tmp, path)
    finally:
        if tmp.exists():
            try:
                tmp.unlink()
            except OSError:
                pass

def sichern(path: Path, data: bytes):
    stempel = datetime.now().astimezone().strftime("%Y%m%dT%H%M%S")
    alt = sorted(path.parent.glob(path.name + ".bak-pinneberg2-*"))
    bak = path.with_name(path.name + ".bak-pinneberg2-" + stempel)
    shutil.copy2(path, bak)
    if bak.read_bytes() != data:
        bak.unlink()
        raise RuntimeError("Sicherung weicht ab")
    for alt_pfad in alt[:-2]:
        try:
            alt_pfad.unlink()
        except OSError:
            pass
    return bak

def apply_dir(ordner: Path, dry: bool, kein: bool) -> int:
    raw, pairs = load()
    rolle = base64.b64decode(raw["rolle"])
    rx = base64.b64decode(raw["rx"])
    json_old = base64.b64decode(raw["json_old"])
    json_new = base64.b64decode(raw["json_new"])
    namen = ("dashboard.py", "prepper_sdr.py", "pinneberg_rolle.py", "ups_manager.py", "lage_pages.py", "pinneberg_rolle.json")
    for name in namen:
        pfad = ordner / name
        if pfad.is_symlink() or not pfad.is_file():
            print("STOP: %s fehlt" % name)
            return 2
    vorher = {name: (ordner/name).read_bytes() for name in namen}
    for name, data in vorher.items():
        if name == "pinneberg_rolle.json":
            digest = sha(data)
            if not (digest.startswith("e0911232") or data == json_new):
                print("STOP: pinneberg_rolle.json %s unbekannt" % digest[:16])
                return 2
            continue
        if not prefix_ok(name, data):
            print("STOP: %s %s ist nicht die installierte Basis" % (name, sha(data)[:16]))
            return 2
    if vorher["prepper_sdr.py"].count(pairs[0][0].encode()) != 1 or vorher["dashboard.py"].count(pairs[2][0].encode()) != 1:
        if rest(vorher["prepper_sdr.py"], pairs[:2], True) and False:
            pass
        schon_sdr = vorher["prepper_sdr.py"].count(pairs[0][1].encode()) == 1 and vorher["prepper_sdr.py"].count(pairs[1][1].encode()) == 1
        schon_dash = vorher["dashboard.py"].count(pairs[2][1].encode()) == 1
        if not (schon_sdr and schon_dash and vorher["pinneberg_rolle.py"] == rolle):
            print("STOP: Pinneberg-Block unbekannt oder gemischt")
            return 2
        print("bereits installiert, keine Aenderung, kein Neustart")
        return 0
    try:
        sdr = tausch(vorher["prepper_sdr.py"], pairs[:2], False)
        dash = tausch(vorher["dashboard.py"], pairs[2:], False)
    except RuntimeError as exc:
        print("STOP: %s" % exc)
        return 2
    if rest(vorher["prepper_sdr.py"], pairs[:2], False) != rest(sdr, pairs[:2], True):
        print("STOP: prepper_sdr.py wuerde ausserhalb der Pinneberg-Stellen geaendert")
        return 2
    if rest(vorher["dashboard.py"], pairs[2:], False) != rest(dash, pairs[2:], True):
        print("STOP: dashboard.py wuerde ausserhalb der Pinneberg-Kachel geaendert")
        return 2
    if syntax(sdr, "prepper_sdr.py") or syntax(dash, "dashboard.py") or syntax(rolle, "pinneberg_rolle.py") or syntax(rx, "pinneberg_rx.py"):
        print("STOP: Syntax")
        return 2
    frei, meldung = fenster()
    print(meldung)
    if not frei and not dry:
        print("STOP: Neustart-Sperre Minute 45-59 und 00-04 Berlin. Nichts geschrieben.")
        return 2
    if dry:
        print("DRY-RUN: kein Backup, kein Schreiben, kein Neustart")
        return 0
    try:
        sichern(ordner/"prepper_sdr.py", vorher["prepper_sdr.py"])
        sichern(ordner/"dashboard.py", vorher["dashboard.py"])
        sichern(ordner/"pinneberg_rolle.py", vorher["pinneberg_rolle.py"])
        sichern(ordner/"pinneberg_rolle.json", vorher["pinneberg_rolle.json"])
        schreiben(ordner/"prepper_sdr.py", sdr)
        schreiben(ordner/"dashboard.py", dash)
        schreiben(ordner/"pinneberg_rolle.py", rolle)
        schreiben(ordner/"pinneberg_rx.py", rx)
        if vorher["pinneberg_rolle.json"] != json_new:
            schreiben(ordner/"pinneberg_rolle.json", json_new)
    except (OSError, RuntimeError) as exc:
        print("STOP beim Schreiben: %s" % exc)
        return 3
    if (ordner/"ups_manager.py").read_bytes() != vorher["ups_manager.py"] or (ordner/"lage_pages.py").read_bytes() != vorher["lage_pages.py"]:
        print("STOP: USV oder Lage wurde angefasst")
        return 3
    print("geschrieben. DSL, Gas, USV und EG-SoH bleiben. Empfang startet erst nach dem Neustart von prepper-sdr.")
    if kein:
        print("Kein Neustart in dieser Pruefung.")
        return 0
    frei, meldung = fenster()
    print(meldung)
    if not frei:
        print("STOP: Dateien sind neu, der Neustart bleibt in der Sperre aus.")
        return 2
    subprocess.run(["systemctl", "restart", "prepper-sdr.service"], check=False)
    subprocess.run(["systemctl", "restart", "prepper-dashboard.service"], check=False)
    print("prepper-sdr und prepper-dashboard neu gestartet. Tunnel und USV nicht.")
    return 0

def selftest() -> int:
    raw, pairs = None, None
    raw, pairs = load()
    blob = ("VOR\n" + pairs[0][0] + "MITTE\n" + pairs[1][0] + "NACH\n# FREMD\n").encode()
    neu = tausch(blob, pairs[:2], False)
    assert rest(blob, pairs[:2], False) == rest(neu, pairs[:2], True)
    assert b"# FREMD" in neu
    assert not fenster(datetime(2026, 11, 12, 12, 10))[0] is False
    assert fenster(datetime(2026, 11, 12, 12, 10))[0]
    assert not fenster(datetime(2026, 11, 12, 9, 50))[0]
    assert not fenster(datetime(2026, 11, 12, 0, 2))[0]
    assert prefix_ok("dashboard.py", b"") is False or True
    print("selftest ok")
    return 0

def load():
    raw = PAYLOAD if isinstance(PAYLOAD, dict) else json.loads(PAYLOAD)
    pairs = [(base64.b64decode(a).decode("utf-8"), base64.b64decode(b).decode("utf-8")) for a, b in raw["pairs"]]
    return raw, pairs

def main(argv):
    args = argv[1:]
    dry = kein = False
    i = 0
    while i < len(args):
        a = args[i]
        if a == "--dry-run":
            dry = True
        elif a == "--kein-neustart":
            kein = True
        elif a == "--selftest":
            return selftest()
        elif a == "--wurzel":
            i += 1
            global DASH
            DASH = Path(args[i])
        else:
            print("STOP: unbekanntes Argument")
            return 2
        i += 1
    return apply_dir(DASH, dry, kein)

